// A pre-existing partial checkpoint, recreated with fictional data.
return [{ json: {
  id: 'demo-a', name: 'Harbor Studio',
  photos: ['Living', 'Kitchen', 'Terrace'],
  completed: [{ photo: 1, caption: 'Fictional living room' }],
  nextPhoto: 1, status: 'PARTIAL'
}}];

const saved = $input.first().json;
const completed = [...saved.completed];
for (let i = saved.nextPhoto; i < saved.photos.length; i++) {
  // LOCAL MOCK: a synthetic label, not an AI API request.
  completed.push({ photo: i + 1, caption: `Mock: ${saved.photos[i]}` });
}
const valid = completed.length === saved.photos.length &&
  completed.every((x, i) => x.photo === i + 1);
return [{ json: { ...saved, completed, nextPhoto: completed.length,
  status: valid ? 'VALIDATED' : 'PARTIAL', safeToExport: valid } }];

const result = $input.first().json;
return [{ json: { status: result.status,
  safePreview: result.safeToExport ? {
    id: result.id, name: result.name, captions: result.completed
  } : null,
  note: 'Demo-only output. No external database is called.'
}}];
